import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

public class Main {
  public static void main(String[] args) throws Exception {
      Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/mibase", "user", "pass");
      Statement stmt = conn.createStatement();

      ResultSet rs = stmt.executeQuery("SELECT * FROM clientes");

      while (rs.next()) {
          // En Java debes acceder manualmente a las columnas por nombre o índice
          String nombre = rs.getString("nombre");
          String direc = rs.getString("direccion");
          System.out.println("Nombre: " + nombre + ", Dir: " + direc);
      }
  }
}
